import {MEDIA_ANIMALS} from './media-art.js';
import {clamp} from './media-core.js';
export const ZOO_REGIONS=[['meadow','Sunny Meadows',0],['jungle','Tropical Jungle',100],['desert','Desert Oasis',130],['snow','Snowy Mountain',150],['ocean','Ocean Cove',180],['fantasy','Fantasy Forest',230],['prehistoric','Prehistoric Park',280],['kingdom','Magical Kingdom',330]].map(([id,name,cost])=>({id,name,cost}));
export const ZOO_PROPS=[['enclosure','Land habitat',30],['water','Water habitat',40],['fence','Fence',5],['path','Path',3],['tree','Tree',12],['bush','Bush',6],['flower','Flowers',5],['rock','Rock',7],['pond','Pond',16],['waterfall','Waterfall',25],['feeder','Feeding station',20],['shelter','Shelter',20],['sign','Sign',8],['playground','Playground',25],['visitor','Visitor area',30],['light','Lighting',9]].map(([id,name,cost])=>({id,name,cost}));
export const TRAITS=['playful','lazy','noisy','shy','friendly','energetic'];
const uuid=()=>globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)+Date.now().toString(36);
export const animalPrice=species=>20+Math.floor(MEDIA_ANIMALS.findIndex(a=>a.id===species)*3.5);
export function newZoo(owner,creative=false){const id=uuid(),cow=MEDIA_ANIMALS.find(a=>a.id==='cow')||MEDIA_ANIMALS[0];return{version:1,owner,creative,coins:80,region:'meadow',regions:creative?ZOO_REGIONS.map(r=>r.id):['meadow'],offlineHours:2,lastSeen:Date.now(),animals:[{id:uuid(),species:cow.id,name:'Moozilla',enclosure:id,x:300,y:300,trait:'friendly',happiness:70,voiceId:null,effect:'Original',volume:.8,muted:false,contributor:owner,voiceBy:null,upgrades:{comfort:0,happiness:0,energy:0,popularity:0,talent:0}}],props:[{id,type:'enclosure',x:300,y:310,w:360,h:280,rotation:0,contributor:owner}],stats:{calls:0,coins:0,recordings:0,pets:0,feeds:0,guesses:0,choirs:0},claims:[],choir:[]};}
export class ZooModel{
 constructor(data,{now=Date.now(),uid=uuid}={}){this.data=structuredClone(data);this.uid=uid;this.clock=0;this.events=[];this.history=[];this.future=[];this.visitors=Array.from({length:8},(_,i)=>({x:i*170,y:100+(i%2)*680,phase:i,state:'walk'}));this.runtime=new Map();this.offline=this.offlineReward(now);this.data.lastSeen=now;for(const a of this.data.animals)this.runtime.set(a.id,{next:1000+Math.random()*4000,talk:0,state:'idle',nextReward:0,lastPet:-30000,lastFeed:-30000,lastPlay:-30000,target:{x:a.x,y:a.y}});}
 offlineReward(now){if(this.data.creative)return 0;const elapsed=clamp((now-this.data.lastSeen)/1000,0,clamp(this.data.offlineHours??2,0,8)*3600);let value=0;for(const a of this.data.animals)if(a.voiceId||a.defaultSound)value+=Math.floor(elapsed/this.interval(a)*this.value(a)*.35);value=Math.min(value,Math.max(300,this.data.animals.length*2000));this.data.coins+=value;return value;}
 interval(a){return Math.max(4,10-(a.trait==='noisy'?2:0)-a.upgrades.energy*.55);}value(a){return 4+Math.floor(MEDIA_ANIMALS.findIndex(s=>s.id===a.species)/7)+a.upgrades.comfort+a.upgrades.happiness+Math.floor(a.happiness/30);}
 get animals(){return this.data.animals;}get props(){return this.data.props;}get coins(){return this.data.coins;}
 earn(n){if(!this.data.creative){this.data.coins+=n;this.data.stats.coins+=n;}}spend(n){if(this.data.creative)return true;if(this.coins<n)return false;this.data.coins-=n;return true;}
 suitable(species,p){const spec=MEDIA_ANIMALS.find(s=>s.id===species);return spec?.group==='Aquatic'?p.type==='water':p.type==='enclosure';}
 rehome(id,habitatId){const a=this.animals.find(a=>a.id===id),p=this.props.find(p=>p.id===habitatId);if(!a||!p||!this.suitable(a.species,p)||this.animals.filter(a=>a.enclosure===p.id).length>=5)return false;const before=this.layout();a.enclosure=p.id;a.x=p.x;a.y=p.y;this.pushLayout(before);return true;}
 adopt(species,contributor=this.data.owner){const spec=MEDIA_ANIMALS.find(a=>a.id===species);if(!spec||this.animals.length>=64)return{error:'The zoo supports up to 64 animals.'};if(spec.group==='Fantasy'&&!this.data.regions.includes('fantasy'))return{error:'Unlock Fantasy Forest first.'};let habitat=this.props.find(p=>this.suitable(species,p)&&this.animals.filter(a=>a.enclosure===p.id).length<5);if(!habitat)return{error:'Build a suitable habitat with space first. Land habitats hold five animals; aquatic animals need water habitats.'};if(!this.spend(animalPrice(species)))return{error:'Earn a few more zoo coins first.'};const a={id:this.uid(),species,name:spec.name,enclosure:habitat.id,x:habitat.x+(Math.random()-.5)*habitat.w*.5,y:habitat.y+(Math.random()-.5)*habitat.h*.5,trait:TRAITS[this.animals.length%6],happiness:65,voiceId:null,effect:'Original',volume:.8,muted:false,contributor,voiceBy:null,upgrades:{comfort:0,happiness:0,energy:0,popularity:0,talent:0}};this.animals.push(a);this.runtime.set(a.id,{next:this.clock+4000,talk:0,state:'idle',nextReward:0,lastPet:-30000,lastFeed:-30000,lastPlay:-30000,target:{x:a.x,y:a.y}});this.events.push({type:'adopt',id:a.id});return{animal:a};}
 assignVoice(id,voiceId,by){const a=this.animals.find(a=>a.id===id);if(!a)return false;const first=!a.voiceId&&!a.everVoiced;a.voiceId=voiceId;a.voiceBy=by;a.defaultSound=false;a.everVoiced=true;if(first){this.data.stats.recordings++;this.earn(18);}this.runtime.get(id).next=this.clock+1200;return true;}
 call(id,{audible=true,manual=false}={}){const a=this.animals.find(a=>a.id===id),r=this.runtime.get(id);if(!a||!r||!a.voiceId&&!a.defaultSound)return null;r.state='talk';r.talk=this.clock+1800;r.next=this.clock+this.interval(a)*1000*(.85+Math.random()*.3);let coins=0;if(this.clock>=r.nextReward){coins=this.value(a);this.earn(coins);this.data.stats.calls++;r.nextReward=this.clock+this.interval(a)*1000*.8;}if(audible){const visitor=this.visitors[Math.floor(this.clock/1000)%this.visitors.length];visitor.state=a.upgrades.popularity%2?'photo':'laugh';visitor.reactionUntil=this.clock+2500;if(coins&&this.clock>=(visitor.nextBonus||0)){const bonus=1+a.upgrades.popularity;this.earn(bonus);visitor.nextBonus=this.clock+15000;this.events.push({type:'visitor',id,coins:bonus});}}this.events.push({type:'call',id,coins,audible});return{animal:a,coins};}
 dueCalls(){return this.animals.filter(a=>(a.voiceId||a.defaultSound)&&this.clock>=this.runtime.get(a.id).next).sort((a,b)=>this.runtime.get(a.id).next-this.runtime.get(b.id).next);}
 interact(id,kind){const a=this.animals.find(a=>a.id===id),r=this.runtime.get(id);if(!a||!r)return false;const key=kind==='feed'?'lastFeed':kind==='play'?'lastPlay':'lastPet';r.state=kind==='feed'?'eat':kind==='play'?'play':'happy';r.actionUntil=this.clock+2500;if(this.clock-r[key]<12000)return true;r[key]=this.clock;a.happiness=Math.min(100,a.happiness+6);this.earn(3);this.data.stats[kind==='feed'?'feeds':'pets']++;return true;}
 upgrade(id,key){const a=this.animals.find(a=>a.id===id);if(!a||!(key in a.upgrades)||a.upgrades[key]>=5)return false;const cost=18+(a.upgrades[key]+1)**2*8;if(!this.spend(cost))return false;a.upgrades[key]++;return true;}
 unlockRegion(id){const r=ZOO_REGIONS.find(r=>r.id===id);if(!r)return false;if(!this.data.regions.includes(id)){if(!this.spend(r.cost))return false;this.data.regions.push(id);}this.data.region=id;return true;}
 layout(){return{props:structuredClone(this.props),positions:this.animals.map(a=>({id:a.id,x:a.x,y:a.y,enclosure:a.enclosure}))};}
 applyLayout(layout){this.data.props=structuredClone(layout.props);for(const p of layout.positions){const a=this.animals.find(a=>a.id===p.id);if(a)Object.assign(a,p);}for(const a of this.animals)if(!this.props.some(p=>p.id===a.enclosure)){const habitat=this.props.find(p=>this.suitable(a.species,p));if(habitat){a.enclosure=habitat.id;a.x=habitat.x;a.y=habitat.y;}}}
 pushLayout(before,cost=0){this.history.push({before,after:this.layout(),cost});if(this.history.length>35)this.history.shift();this.future=[];}
 addProp(type,x,y,by=this.data.owner){const spec=ZOO_PROPS.find(p=>p.id===type);if(!spec||this.props.length>=180||!this.spend(spec.cost))return false;const before=this.layout(),habitat=['enclosure','water'].includes(type),p={id:this.uid(),type,x:clamp(x,habitat?190:45,habitat?1410:1555),y:clamp(y,habitat?160:45,habitat?840:955),w:habitat?340:90,h:habitat?260:90,rotation:0,contributor:by};this.props.push(p);this.pushLayout(before,spec.cost);return p;}
 moveProp(id,x,y){const p=this.props.find(p=>p.id===id);if(!p)return;const before=this.layout(),nx=clamp(x,p.w/2,1600-p.w/2),ny=clamp(y,p.h/2,1000-p.h/2),dx=nx-p.x,dy=ny-p.y;p.x=nx;p.y=ny;for(const a of this.animals.filter(a=>a.enclosure===id)){a.x+=dx;a.y+=dy;}this.pushLayout(before);}
 removeProp(id){if(this.animals.some(a=>a.enclosure===id))return false;const before=this.layout();this.data.props=this.props.filter(p=>p.id!==id);this.pushLayout(before);return true;}
 rotateProp(id){const p=this.props.find(p=>p.id===id);if(!p||['enclosure','water'].includes(p.type))return false;const before=this.layout();p.rotation=(p.rotation||0)+Math.PI/4;this.pushLayout(before);return true;}
 undo(){const row=this.history.at(-1);if(!row)return false;if(this.animals.some(a=>!row.before.props.some(p=>p.id===a.enclosure)&&!row.before.positions.some(p=>p.id===a.id))){return false;}this.history.pop();this.applyLayout(row.before);if(!this.data.creative)this.data.coins+=row.cost;this.future.push(row);}redo(){const row=this.future.at(-1);if(!row||!this.spend(row.cost))return;this.future.pop();this.applyLayout(row.after);this.history.push(row);}
 discoveries(){return[{id:'five',name:'Adopt five species',done:new Set(this.animals.map(a=>a.species)).size>=5,reward:90},{id:'homes',name:'Build three habitats',done:this.props.filter(p=>['water','enclosure'].includes(p.type)).length>=3,reward:60},{id:'voices',name:'Give ten animals your voice',done:this.animals.filter(a=>a.voiceId).length>=10,reward:140},{id:'jungle',name:'Unlock Tropical Jungle',done:this.data.regions.includes('jungle'),reward:60},{id:'choir',name:'Create a four-animal choir',done:this.data.stats.choirs>0,reward:65},{id:'decorate',name:'Place six decorations',done:this.props.filter(p=>!['water','enclosure'].includes(p.type)).length>=6,reward:50}];}
 claim(id){const row=this.discoveries().find(r=>r.id===id);if(!row?.done||this.data.claims.includes(id))return false;this.data.claims.push(id);this.earn(row.reward);return true;}
 tick(dt){dt=Math.min(150,Math.max(0,dt));this.clock+=dt;for(const a of this.animals){const r=this.runtime.get(a.id),p=this.props.find(p=>p.id===a.enclosure);if(!p)continue;if(r.talk>this.clock)r.state='talk';else if(r.actionUntil>this.clock){}else{const phase=(this.clock/1000+a.id.length*3)%26;if(a.trait==='lazy'&&phase<12)r.state='sleep';else if(a.trait==='shy'&&phase<10)r.state='sit';else r.state=phase<19?'walk':'idle';}if(r.state==='walk'||r.state==='play'){const speed=a.trait==='energetic'?31:a.trait==='playful'?24:13;if(a.trait==='friendly'){const friend=this.animals.find(b=>b.id!==a.id&&b.enclosure===a.enclosure);if(friend&&Math.hypot(friend.x-a.x,friend.y-a.y)>90){a.x+=Math.sign(friend.x-a.x)*dt*.008;a.y+=Math.sign(friend.y-a.y)*dt*.008;}}a.x+=Math.sin(this.clock/2400+a.id.charCodeAt(0))*speed*dt/1000;a.y+=Math.cos(this.clock/3000+a.id.charCodeAt(1))*speed*.5*dt/1000;}a.x=clamp(a.x,p.x-p.w/2+60,p.x+p.w/2-60);a.y=clamp(a.y,p.y-p.h/2+60,p.y+p.h/2-50);}for(let i=0;i<this.visitors.length;i++){const v=this.visitors[i];v.x=(v.x+dt*(.018+i*.002))%1600;v.y=70+(i%2)*850+Math.sin(this.clock/1500+i)*12;if(!(v.reactionUntil>this.clock))v.state=this.clock%11000<2000?'photo':'walk';}}
 snapshot(now=Date.now()){this.data.lastSeen=now;return structuredClone(this.data);}
}
export class GuessGame{constructor(animals,{seed=42,players=1,difficulty=3}={}){this.pool=animals.filter(a=>a.voiceId);this.players=players;this.difficulty=difficulty;this.turn=0;this.round=0;this.scores=Array(players).fill(0);this.times=Array(players).fill(0);this.seed=seed;this.done=false;this.started=0;}next(now){if(this.round>=5*this.players||this.pool.length<2){this.done=true;return null;}this.turn=this.round%this.players;let n=(Math.imul(this.seed+(this.round%this.players*7+Math.floor(this.round/this.players))*33,1664525)+1013904223)>>>0;this.target=this.pool[n%this.pool.length];const other=this.pool.filter(a=>a.id!==this.target.id);for(let i=other.length-1;i>0;i--){n=(Math.imul(n,1664525)+1013904223)>>>0;const j=n%(i+1);[other[i],other[j]]=[other[j],other[i]];}this.choices=[this.target,...other.slice(0,[2,3,4,6,8][this.difficulty-1]-1)];this.started=now;return this.target;}answer(id,now){if(!this.target||this.done)return false;const correct=id===this.target.id;if(correct)this.scores[this.turn]++;this.times[this.turn]+=Math.min(15000,Math.max(0,now-this.started));this.round++;this.target=null;if(this.round>=5*this.players)this.done=true;return correct;}}
